const trigger = $input.first().json.body || $input.first().json;
const userMsg = trigger.user_message || '';
const assistantMsg = trigger.assistant_message || '';
const sessionId = trigger.session_id || '';

const requestBody = {
  requests: [
    {
      type: 'execute',
      stmt: {
        sql: "SELECT content FROM prompts WHERE key = 'extractor' LIMIT 1"
      }
    },
    {
      type: 'execute',
      stmt: {
        sql: 'SELECT id, fact, category, strength FROM facts ORDER BY strength DESC LIMIT 50'
      }
    }
  ]
};

return [{ json: { requestBody, userMsg, assistantMsg, sessionId } }];

const dbResult = $input.first().json;
const prevData = $('Build DB Request').first().json;

const results = dbResult.results || [];
const parseRows = (result) => {
  if (!result || !result.response || !result.response.result) return [];
  const cols = result.response.result.columns || result.response.result.cols || [];
  const rows = result.response.result.rows || [];
  return rows.map(row => {
    const obj = {};
    cols.forEach((col, i) => {
      const cell = row[i];
      obj[col.name] = (cell && typeof cell === 'object' && 'value' in cell) ? cell.value : cell;
    });
    return obj;
  });
};

const extractorPrompt = parseRows(results[0])[0]?.content || '';
const existingFacts = parseRows(results[1]);

const factsList = existingFacts.map(f => `[${f.id}] ${f.fact} (${f.category}, strength: ${f.strength})`).join('\n');

const messages = [
  { role: 'system', content: extractorPrompt },
  { role: 'user', content: 'EXISTING FACTS:\n' + (factsList || 'None yet.') + '\n\nCONVERSATION TO ANALYZE:\nUser: ' + prevData.userMsg + '\nClara: ' + prevData.assistantMsg + '\n\nExtract facts about the USER (not Clara). Return JSON only.' }
];

return [{ json: { messages, sessionId: prevData.sessionId, userMsg: prevData.userMsg, assistantMsg: prevData.assistantMsg } }];

const llmResponse = $input.first().json;
const content = (llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message && llmResponse.choices[0].message.content) || '';
const prevData = $('Build Extraction Prompt').first().json;
const sessionId = prevData.sessionId;

let raw;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  raw = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  raw = { facts: [] };
}

// Handle multiple formats
let factsToSave = [];

// Format 1: { extract: true, facts: [{ fact: '...', category: '...', confidence: 0.8 }] }
if (raw.extract && Array.isArray(raw.facts)) {
  factsToSave = raw.facts;
}
// Format 2: { facts: ['string1', 'string2'] }
else if (Array.isArray(raw.facts)) {
  factsToSave = raw.facts.map(f => {
    if (typeof f === 'string') return { fact: f, category: 'general', confidence: 0.7 };
    return f;
  });
}
// Format 3: { extracted_facts: [...] }
else if (raw.extracted_facts && Array.isArray(raw.extracted_facts)) {
  factsToSave = raw.extracted_facts.map(f => {
    if (typeof f === 'string') return { fact: f, category: 'general', confidence: 0.7 };
    return f;
  });
}

const requests = factsToSave.map(f => ({
  type: 'execute',
  stmt: {
    sql: 'INSERT INTO facts (fact, category, confidence, source_session) VALUES (?, ?, ?, ?)',
    args: [
      { type: 'text', value: f.fact || f.text || f.description || '' },
      { type: 'text', value: f.category || 'general' },
      { type: 'float', value: f.confidence || 0.7 },
      { type: 'text', value: sessionId }
    ]
  }
}));

return [{ json: { requestBody: { requests }, sessionId } }];
